<div class="table-responsive slaughter-table-wrap"><table class="enterprise-table slaughter-table" data-datatable="false" aria-label="Abattages à la ferme"><thead><tr><?php foreach(['reference'=>'Abattage / lot','date'=>'Date','heads'=>'Porcs','weight'=>'Carcasses (kg)','expiry'=>'DLC','state'=>'État'] as$key=>$label):?><th scope="col" class="<?=in_array($key,['heads','weight'],true)?'num':''?>" aria-sort="none"><button type="button" data-flow-sort="<?=e($key)?>"><?=e($label)?> <span aria-hidden="true">↕</span></button></th><?php endforeach;?><th scope="col">Actions</th></tr></thead><tbody data-flow-table-body>
<?php foreach($farm['slaughters'] as$s):?><tr data-slaughter-id="<?=e($s['id'])?>" data-flow-item data-flow-key="slaughter-<?=e($s['id'])?>" data-kind="slaughter" data-state="<?=e($s['status'])?>" data-reference="<?=e($s['conversion_number'])?>" data-date="<?=e($s['converted_at'])?>" data-heads="<?=(int)$s['input_heads']?>" data-weight="<?=e($s['net_weight_kg'])?>" data-expiry="<?=e($s['expiry_date'])?>" data-search="<?=e($s['site_name'].' '.$s['batch_number'].' '.$s['conversion_number'].' '.$s['author'].' '.$s['validator'])?>">
<td data-label="Abattage / lot"><strong><?=e($s['conversion_number'])?></strong><small><?=e($s['site_name'])?></small><small><?=e($s['batch_number'])?></small></td><td data-label="Date"><?=e(date('d/m/Y H:i',strtotime($s['converted_at'])))?></td><td class="num" data-label="Porcs"><strong><?=(int)$s['input_heads']?></strong></td><td class="num" data-label="Carcasses (kg)"><?=$kg($s['net_weight_kg'])?></td><td data-label="DLC"><?=e(date('d/m/Y',strtotime($s['expiry_date'])))?></td><td data-label="État"><span class="status-badge ui-status ui-status--<?=e($statusTone($s['status']))?>"><?=e($statusLabels[$s['status']]??$s['status'])?></span></td><td data-label="Actions"><details class="slaughter-row-actions"><summary>Détails et actions</summary><p>Enregistré par <?=e($s['author'])?><?=$s['validator']?' · Validé par '.e($s['validator']):''?></p><?php if($s['status']==='submitted'&&Auth::can('livestock','validate',(int)$s['site_id'])): $inlineForm=true;$action='livestock/pigs/slaughters/'.$s['id'].'/validate';$confirm='Valider cet abattage et retirer ces porcs de l’effectif vivant ?';require __DIR__.'/form_start.php'; ?><p>Confirmez les <?=(int)$s['input_heads']?> porcs abattus et les <?=$kg($s['net_weight_kg'])?> kg de carcasses pesées.</p><?php $submitLabel='Valider l’abattage';require __DIR__.'/form_end.php';unset($inlineForm); ?><?php elseif($s['status']==='validated'): ?><a class="btn-secondary" href="<?=e(base_url('livestock/pigs/shipments'))?>"><i class="bi bi-truck" aria-hidden="true"></i> Préparer un envoi</a><?php endif; ?><?php if($s['status']==='submitted'&&Auth::can('livestock','delete',(int)$s['site_id'])):$action='livestock/pigs/slaughters/'.$s['id'].'/cancel';require __DIR__.'/cancel_form.php';endif; ?></details></td></tr><?php endforeach;?></tbody></table></div>
